/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Method,
  Prop,
  Watch,
} from '@stencil/core';

/**
 * @slot title - tab title (any HTML allowed, include icons etc. here) - please note that the content of the tab title cannot overflow the tabs header
 * @slot default - tab content
 */
@Component({
  tag: 'groupui-tab',
  styleUrl: 'tab.scss',
  shadow: true,
})
export class Tab implements ComponentInterface {
  /**
   * internal property to allow the parent component to mark this tab as active. Should not be used manually.
   * @internal
   */
  @Prop({ reflect: true, mutable: true }) active = false;

  /**
   * disables the current tab
   */
  @Prop() readonly disabled: boolean;

  /**
   * The description can only be used with a disabled content and is optional
   */
  @Prop({ reflect: true }) readonly disabledDescription: string;

  /**
   * A tab id can be provided for each `groupui-tab`. It's used internally to reference
   * the selected tab to switch between them. If none given a generic one will be created.
   */
  @Prop({ reflect: true }) readonly tab: string = Math.random().toString(36).substring(7);

  /**
   * fired on tab change
   */
  @Event() tabChanged: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /** Set the active component for the tab */
  @Method()
  async setActive(): Promise<void> {
    this.active = true;
  }

  /** Updates the tab */
  @Method()
  async update(): Promise<void> {
    this.tabChanged.emit();
  }

  @Watch('disabled')
  onRenderRelevantPropChange() {
    this.tabChanged.emit();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'ArrowRight') {
      event.stopPropagation();
    }
    if (event.code === 'ArrowLeft') {
      event.stopPropagation();
    }
    if (event.code === 'Home') {
      event.stopPropagation();
    }
    if (event.code === 'End') {
      event.stopPropagation();
    }
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    const { tab, active } = this;
    return (
      <Host
        role="tabpanel"
        aria-hidden={!active ? 'true' : null}
        aria-labelledby={`tab-button-${tab}`}
        class={{ 'tab-hidden': !active }}
      >
        <slot />
      </Host>
    );
  }
}
